_RACE_RUN_ID = "cccccccccccccccccccccccccccccccc"


class _CompensatingStartJournal(PromptJournal):
    """Journal whose accepted start loses the running CAS to a cancel."""

    def __init__(self, db, *, run_status_after_start: str) -> None:
        self.cancel_calls: list[dict[str, str]] = []
        self._db = db
        self._run_status_after_start = run_status_after_start

    async def start(self, **kwargs) -> PromptRun:
        session_id = str(kwargs["session_id"])
        self._db.execute(
            """INSERT INTO prompt_runs (id, session_id, idempotency_key, status)
               VALUES (?, ?, ?, 'starting')""",
            (_RACE_RUN_ID, session_id, str(kwargs["idempotency_key"])),
        )
        if self._run_status_after_start != "starting":
            self._db.execute(
                "UPDATE prompt_runs SET status = ? WHERE id = ?",
                (self._run_status_after_start, _RACE_RUN_ID),
            )
        self._db.execute(
            """UPDATE thread_delegations
               SET status = 'cancelled', completed_at = CURRENT_TIMESTAMP,
                   updated_at = CURRENT_TIMESTAMP
               WHERE child_session_id = ? AND status = 'queued'""",
            (session_id,),
        )
        self._db.commit()
        return PromptRun(id=_RACE_RUN_ID, session_id=session_id, status="starting")

    async def cancel(self, *, request, session_id, run_id) -> PromptRun:
        self.cancel_calls.append(
            {"session_id": str(session_id), "run_id": str(run_id)}
        )
        row = self._db.execute(
            "SELECT status FROM prompt_runs WHERE id = ?", (str(run_id),)
        ).fetchone()
        if row is not None and row["status"] not in ("completed", "failed"):
            self._db.execute(
                "UPDATE prompt_runs SET status = 'cancelled' WHERE id = ?",
                (str(run_id),),
            )
            self._db.commit()
        return PromptRun(
            id=str(run_id),
            session_id=str(session_id),
            status="completed" if self._run_status_after_start == "completed" else "cancelled",
        )


